from .schema import B, concept as C, step as S, example as E, lab as P, quiz as Q, lesson as L
LESSONS = [
L('OS-L01',B('Orientarse, leer y transformar archivos','Navigate, read and transform files'),B('¿Dónde se ejecuta realmente tu orden?','Where is your command actually running?'),B('Trabajar con rutas y tuberías sin confundir texto, nombres y código.','Use paths and pipelines without confusing text, names and code.'),[
 C(B('Una ubicación antes de una acción','Location before action'),B('El prompt es una pista, no una prueba de identidad. pwd identifica el directorio; id muestra la identidad; /etc/os-release identifica la distribución. /etc contiene configuración, /var datos variables y logs, /home perfiles y /run estado de ejecución. /proc y /sys exponen interfaces del kernel: no son carpetas ordinarias para guardar documentos. Las rutas relativas parten del directorio actual, no del lugar donde guardaste un script.','The prompt is a clue, not proof of identity. pwd identifies the directory; id shows identity; /etc/os-release identifies the distribution. /etc holds configuration, /var variable data and logs, /home user homes and /run runtime state. /proc and /sys expose kernel interfaces rather than ordinary document storage. Relative paths start at the working directory, not at the location where a script was saved.'),B('Host, identidad, directorio e intérprete primero.','Host, identity, directory and interpreter first.')),
 C(B('El shell transforma argumentos','The shell transforms arguments'),B('Antes de lanzar un programa, Bash expande variables y patrones. Una ruta con espacios sin comillas puede convertirse en varios argumentos. Las comillas simples conservan texto literal; las dobles permiten determinadas expansiones manteniendo el argumento agrupado. Un glob como *.log no es una expresión regular. Los nombres son datos: nunca deben convertirse en código mediante eval.','Before launching a program, Bash expands variables and patterns. An unquoted path containing spaces may become several arguments. Single quotes preserve literal text; double quotes allow selected expansion while keeping the argument together. A glob such as *.log is not a regular expression. Names are data and must not become executable code through eval.'),B('Cita rutas; no ejecutes sus nombres.','Quote paths; do not execute their names.')),
 C(B('Filtrar con un resultado comprobable','Filter with a checkable result'),B('Una tubería conecta la salida de un proceso con la entrada de otro. Normalmente circulan bytes o texto, no objetos administrativos. grep selecciona líneas; sort ordena; uniq compara líneas contiguas; awk procesa campos. Conserva el original y define delimitadores y codificación. Que no aparezcan coincidencias puede ser correcto; un error de lectura debe distinguirse de cero resultados.','A pipeline connects one process output to another input. Usually it transports bytes or text, not administrative objects. grep selects lines, sort orders, uniq compares adjacent lines and awk processes fields. Preserve the original and specify delimiters and encoding. No matches can be correct; a read error must be distinguished from zero results.'),B('Transformar no debe borrar procedencia ni errores.','Transformation must preserve provenance and errors.'))],
 [B('Carpeta aislada','Isolated folder'),B('Archivo de entrada','Input file'),B('Filtro explícito','Explicit filter'),B('Resultado contrastado','Checked result')],
 E(B('Contar estados sin tocar el original','Count states without modifying the input'),'Bash',"work=$(mktemp -d)\nprintf 'equipo,estado\naula1,ok\naula2,fallo\naula3,ok\n' > \"$work/inventario.csv\"\nawk -F, 'NR>1 {print $2}' \"$work/inventario.csv\" | sort | uniq -c",B('Dos líneas de resumen: fallo aparece 1 vez y ok 2 veces; los espacios de alineación pueden variar.','Two summary lines: fallo occurs once and ok twice; alignment spaces may vary.'),B('mktemp crea un directorio nuevo. La cabecera se excluye con NR>1 y no se modifica el CSV. Este parser solo sirve para el CSV sencillo del ejercicio, no para campos entrecomillados con comas.','mktemp creates a new directory. NR>1 excludes the header and the CSV stays unchanged. This parser only fits the simple exercise CSV, not quoted fields containing commas.')),
 P(B('Linux con Bash y utilidades estándar; cuenta normal. Cada ejecución usa el directorio nuevo del ejemplo.','Linux with Bash and standard utilities; ordinary account. Each run uses the new example directory.'),[
 S(B('Identifica contexto y lee la ayuda antes de generar datos.','Identify context and consult help before generating data.'),B('Registra versión e identidad sin volcar variables de entorno.','Record version and identity without dumping environment variables.'),'pwd; id; cat /etc/os-release'),
 S(B('Ejecuta el ejemplo y cuenta manualmente las filas.','Run the example and count rows manually.'),B('La suma de grupos es 3; no incluye la cabecera.','Group counts sum to 3, excluding the header.')),
 S(B('Copia el CSV a un nombre con espacios y repite el filtro con comillas.','Copy the CSV to a name with spaces and repeat the quoted filter.'),B('Mismos resultados; dos archivos diferentes.','Same results; two separate files.'),'cp -- "$work/inventario.csv" "$work/inventario aula.csv"'),
 S(B('Busca un estado inexistente y luego intenta leer un archivo que no existe.','Search for a missing state, then try reading a nonexistent file.'),B('Distingue ausencia de coincidencia y error mediante stderr y estado.','Distinguish no match from an error using stderr and status.'),'grep -F "desconocido" "$work/inventario.csv"; printf "estado=%s\n" "$?"')],B('CSV original, resumen y explicación de los dos resultados negativos.','Original CSV, summary and explanation of both negative outcomes.'),B('Reproduces el conteo y explicas por qué las comillas y la cabecera importan.','Reproduce the count and explain quoting and the header.'),B('Guarda evidencia; elimina solo los dos archivos conocidos y después el directorio vacío con rmdir, revisando la variable work.','Save evidence; remove only the two known files and then the empty directory with rmdir after checking work.'),B('Al cambiar de terminal, work está vacío.','After changing terminals, work is empty.'),B('Las variables no se comparten automáticamente entre shells. Localiza el directorio registrado o repite el ejemplo en uno nuevo.','Variables are not automatically shared between shells. Locate the recorded directory or repeat with a new one.')),
 Q(B('¿uniq agrupa duplicados no contiguos por sí solo?','Does uniq group nonadjacent duplicates by itself?'),[B('Sí.','Yes.'),B('No; compara líneas adyacentes.','No; it compares adjacent lines.'),B('Solo si hay cabecera.','Only with a header.')],1,B('Ordena primero cuando el contrato requiere agrupar todas las coincidencias.','Sort first when the contract requires grouping all matches.')),B('Recorrer archivos interpretando la salida visual de ls.','Iterating files by parsing the visual output of ls.'),B('Una orden es reproducible cuando contexto, entrada y resultado están definidos.','A command is reproducible when context, input and result are defined.'),['bash','coreutils'],['M04','M05','M06']),
L('OS-L02',B('Usuarios, permisos y acceso efectivo','Users, permissions and effective access'),B('El modo parece correcto; ¿por qué el usuario sigue sin entrar?','The mode looks correct; why is access still denied?'),B('Verificar acceso local y explicar grupos, ACL, sudo y directorios.','Verify local access and explain groups, ACLs, sudo and directories.'),[
 C(B('Identidad numérica y resolución','Numeric identity and resolution'),B('El kernel decide con identificadores y credenciales del proceso; un nombre es su representación. getent consulta las fuentes configuradas mediante NSS, que pueden incluir archivos locales o un directorio. PAM interviene en los flujos de autenticación que lo utilizan; SSSD integra identidad y autenticación en escenarios definidos. Una respuesta LDAP no demuestra por sí sola que un usuario pueda iniciar sesión.','The kernel makes decisions using process identifiers and credentials; a name is their representation. getent queries sources configured through NSS, potentially including local files or a directory. PAM participates in authentication flows using it; SSSD integrates identity and authentication for defined scenarios. An LDAP response alone does not prove a user can log in.'),B('Resolver una identidad no equivale a iniciar sesión.','Resolving identity is not logging in.')),
 C(B('Permisos de archivo y de directorio','File and directory permissions'),B('En un archivo, r permite leer contenido y w modificarlo; x permite intentar ejecutarlo. En un directorio, x permite atravesarlo y acceder a nombres conocidos; r listar nombres y w modificar sus entradas, sujeto a otros controles. Por eso borrar un archivo depende de su directorio y no solo de su bit w. umask limita permisos iniciales, no modifica retroactivamente archivos existentes.','For a file, r allows reading contents, w modification and x attempting execution. For a directory, x allows traversal and access to known names, r listing names and w changing directory entries, subject to other controls. Deleting a file therefore depends on its directory, not only its w bit. umask limits initial permissions; it does not retroactively change existing files.'),B('El significado de rwx depende del objeto.','The meaning of rwx depends on the object.')),
 C(B('ACL y privilegio delegado','ACLs and delegated privilege'),B('Una ACL añade entradas y una máscara que puede limitar permisos efectivos. También deben comprobarse los directorios padres, grupos de la sesión y SELinux/AppArmor cuando estén activos. sudo delega acciones según política; no equivale a cambiar de carpeta o variable USER. La baja debe revisar cuentas locales, sesiones, claves y dependencia de servicios; evita borrar datos antes de decidir su conservación.','An ACL adds entries and a mask that can limit effective permissions. Parent directories, session groups and active SELinux/AppArmor policy also matter. sudo delegates actions under policy; changing directory or USER does not. Offboarding must consider local accounts, sessions, keys and service dependencies; avoid deleting data before deciding retention.'),B('Inspecciona todas las capas; delega lo mínimo.','Inspect all layers; delegate the minimum.'))],
 [B('UID y grupos','UID and groups'),B('Recorrido de padres','Parent traversal'),B('Modo + ACL + política','Mode + ACL + policy'),B('Leer / escribir / denegar','Read / write / deny')],
 E(B('Acceso de solo lectura','Read-only access'),'Bash · Linux VM',"d=$(mktemp -d)\nprintf 'documento ficticio\n' > \"$d/nota.txt\"\nchmod 700 \"$d\"\nchmod 600 \"$d/nota.txt\"\nstat -c '%a %n' \"$d\" \"$d/nota.txt\"",B('El directorio muestra 700 y el archivo 600. No se han cambiado recursos ajenos.','The directory shows 700 and the file 600. No unrelated resources changed.'),B('Esta preparación protege el dataset del propietario. No prueba todavía la identidad lectora: la práctica añade una ACL acotada y ejecuta una operación con esa cuenta.','This setup protects the owner dataset. Reader access is not yet proved: the lab adds a scoped ACL and performs an operation under that identity.')),
 P(B('VM Linux desechable, ACL instaladas, cuenta osreader creada y autorizada por el docente; privilegio para ejecutar como esa cuenta. Sin estos requisitos, registra la parte nativa como pendiente.','Disposable Linux VM, ACL tools installed, instructor-created authorized osreader account and permission to run as it. Without these prerequisites, record native testing as pending.'),[
 S(B('Ejecuta el ejemplo y registra identidad y ruta.','Run the example and record identity and path.'),B('La ruta d es nueva y está bajo /tmp; comprueba sus padres.','d is new under /tmp; check its parents.'),'id; getent passwd osreader; namei -l "$d/nota.txt"'),
 S(B('Concede recorrido y lectura exclusivamente al lector del laboratorio.','Grant traversal and reading only to the lab reader.'),B('getfacl muestra entradas y máscara efectiva.','getfacl shows entries and effective mask.'),'setfacl -m u:osreader:rx "$d"; setfacl -m u:osreader:r-- "$d/nota.txt"; getfacl "$d/nota.txt"'),
 S(B('Prueba contenido legible y permiso de escritura denegado con la cuenta lectora.','Test readable content and denied write permission under the reader account.'),B('cat funciona; test -w devuelve no cero. Captura cada estado inmediatamente.','cat succeeds; test -w returns nonzero. Capture each status immediately.'),'sudo -u osreader cat -- "$d/nota.txt"; sudo -u osreader test -w "$d/nota.txt"; printf "escritura=%s\n" "$?"'),
 S(B('Revoca las dos entradas y repite la lectura.','Revoke both entries and repeat the read.'),B('Se deniega acceso; la cuenta no se modifica.','Access is denied; the account itself is unchanged.'),'setfacl -x u:osreader "$d/nota.txt"; setfacl -x u:osreader "$d"')],B('ACL antes/después y tres pruebas identificadas.','Before/after ACL and three identified checks.'),B('Demuestras permitir lectura, negar escritura y revocar acceso.','Demonstrate allowed read, denied write and revoked access.'),B('Verifica revocación; retira nota.txt y el directorio vacío. No elimines la cuenta docente.','Verify revocation; remove nota.txt and the empty directory. Do not delete the instructor account.'),B('setfacl no existe o el filesystem no soporta la operación.','setfacl is missing or the filesystem does not support the operation.'),B('Registra el prerrequisito fallido; usa la VM/volumen admitido. No sustituyas la ACL por chmod 777.','Record the failed prerequisite and use the supported VM/volume. Do not substitute chmod 777.')),
 Q(B('¿Qué permite x sobre un directorio?','What does x permit on a directory?'),[B('Ejecutar cualquier archivo ignorando sus permisos.','Execute every file regardless of permissions.'),B('Atravesarlo para acceder a nombres conocidos.','Traverse it to access known names.'),B('Leer todo su contenido.','Read all contents.')],1,B('El acceso final sigue sujeto a los permisos del objeto.','Final access remains subject to object permissions.')),B('Conceder acceso global para resolver un fallo de identidad o ACL.','Granting global access to solve an identity or ACL failure.'),B('Un control se verifica desde el sujeto y la operación previstos.','Verify a control from the intended subject and operation.'),['coreutils','ubuntu-sssd'],['M07']),
L('OS-L03',B('Procesos, paquetes, servicios y tareas','Processes, packages, services and jobs'),B('¿Un servicio inactivo puede haber terminado correctamente?','Can an inactive service have completed successfully?'),B('Operar una unidad de usuario sin confundir ejecución, habilitación y salud.','Operate a user unit without confusing execution, enablement and health.'),[
 C(B('Gestor de servicio y proceso','Service manager and process'),B('systemd relaciona unidades, dependencias, identidad y resultados. start ejecuta ahora; enable prepara la activación según la unidad, pero no garantiza actividad actual. Un oneshot hace una tarea finita. Sin RemainAfterExit puede terminar correctamente y quedar inactivo: consulta Result y ExecMainStatus, no solo una palabra de color. Un servicio de usuario tiene ámbito y ciclo de vida diferentes al de sistema.','systemd relates units, dependencies, identity and outcomes. start runs now; enable configures activation according to the unit, but does not guarantee current activity. A oneshot performs a finite task. Without RemainAfterExit it can succeed and become inactive: inspect Result and ExecMainStatus rather than a colored status word. User services have different scope and lifetime from system services.'),B('Inactivo no es automáticamente fallido.','Inactive does not automatically mean failed.')),
 C(B('Paquetes y procedencia','Packages and provenance'),B('apt/dpkg y dnf/rpm pertenecen a familias distintas. El gestor resuelve dependencias y verifica procedencia según repositorios y confianza configurados. Instalar no equivale a habilitar ni exponer un servicio; hay que comprobarlo. Una actualización se prueba primero en una copia con un criterio funcional y recuperación. No añadas repositorios ni ejecutes instaladores remotos con privilegios para saltar un error.','apt/dpkg and dnf/rpm belong to different distribution families. Package managers resolve dependencies and verify provenance under configured repositories and trust. Installation is not equivalent to enabling or exposing a service; check the result. Test updates on a copy with functional criteria and recovery. Do not add repositories or run privileged remote installers just to bypass an error.'),B('Origen, versión y efecto efectivo.','Origin, version and actual effect.')),
 C(B('Entorno no interactivo','Noninteractive environment'),B('cron y timers no heredan necesariamente PATH, directorio o variables de tu terminal. Usa rutas verificadas, identidad mínima, salida de errores y control de duplicados. La tarea debe funcionar a mano antes de programarla. La evidencia incluye una ejecución correcta, un fallo controlado y la retirada de la programación; no es suficiente una captura del calendario.','cron and timers do not necessarily inherit your terminal PATH, directory or variables. Use verified paths, least privilege, error output and duplicate controls. A job must work manually before scheduling. Evidence includes a successful run, controlled failure and schedule removal, not just a screenshot of a calendar.'),B('El entorno es parte del contrato.','The environment is part of the contract.'))],
 [B('Unidad validada','Validated unit'),B('Gestor de usuario','User manager'),B('Proceso finito','Finite process'),B('Resultado y journal','Result and journal')],
 E(B('Unidad sin cambios privilegiados','Unit without privileged changes'),'systemd unit','[Unit]\nDescription=OS classroom finite demonstration\n[Service]\nType=oneshot\nExecStart=/usr/bin/printf aula-ok\\n',B('Al iniciarla debe registrar aula-ok y terminar sin error; no permanece activa.','Starting it should log aula-ok and finish successfully; it does not remain active.'),B('Guarda como ~/.config/systemd/user/os-classroom-demo.service tras comprobar que no existe. Verifica primero la ruta con command -v printf o type -a printf. No añadas Enable, timers o privilegios para esta demostración.','Save as ~/.config/systemd/user/os-classroom-demo.service after checking it does not exist. Verify the executable path first with command -v printf or type -a printf. Do not add enablement, timers or privileges for this demonstration.')),
 P(B('VM Linux con systemd y gestor de usuario disponible. No válido en cualquier contenedor. Nombre de unidad reservado al ejercicio.','Linux VM with systemd and a working user manager. Not valid in every container. The unit name is reserved for this exercise.'),[
 S(B('Comprueba el gestor de usuario y que no exista la unidad.','Check the user manager and confirm the unit does not exist.'),B('No sobrescribas un trabajo previo.','Do not overwrite an existing job.'),'systemctl --user list-unit-files os-classroom-demo.service'),
 S(B('Crea el directorio si falta y guarda el texto del ejemplo con un editor.','Create the directory if needed and save the example with an editor.'),B('Unidad propia, ruta absoluta del ejecutable verificada.','Own unit with verified absolute executable path.'),'mkdir -p "$HOME/.config/systemd/user"'),
 S(B('Recarga definiciones, inicia y consulta el resultado.','Reload definitions, start and inspect the result.'),B('Result=success, ExecMainStatus=0; inactive es admisible para este oneshot.','Result=success, ExecMainStatus=0; inactive is acceptable for this oneshot.'),'systemctl --user daemon-reload; systemctl --user start os-classroom-demo.service; systemctl --user show os-classroom-demo.service -p Result -p ExecMainStatus -p ActiveState'),
 S(B('Consulta únicamente su journal y retira la unidad después.','Read only this unit journal and remove the unit afterwards.'),B('Atribuyes el mensaje a unidad e intervalo, no a todo el equipo.','Attribute the message to unit and interval, not the whole machine.'),'journalctl --user -u os-classroom-demo.service --since "10 minutes ago" --no-pager')],B('Unidad, resultado y extracto acotado.','Unit, result and scoped log excerpt.'),B('Explicas el estado final y reproduces el mensaje sin sudo.','Explain final state and reproduce the message without sudo.'),B('Detén la unidad, elimina solo su fichero y ejecuta daemon-reload de usuario. No purgues journal.','Stop the unit, remove only its file and reload the user manager. Do not purge the journal.'),B('No hay bus o gestor de usuario.','No user bus or manager exists.'),B('Es un prerrequisito del entorno, no un fallo que deba resolverse como root. Usa la VM con sesión admitida.','This is an environment prerequisite, not a reason to run as root. Use the VM with a supported session.')),
 Q(B('¿enable prueba que un servicio responde correctamente?','Does enable prove a service responds correctly?'),[B('Sí.','Yes.'),B('No; activación y salud son distintas.','No; activation and health differ.'),B('Solo si usa root.','Only when using root.')],1,B('Comprueba estado actual y una operación funcional.','Check current state and a functional operation.')),B('Reiniciar todo antes de leer el resultado del servicio.','Restarting everything before reading service results.'),B('Primero contrato de ejecución; después programación.','Execution contract first; scheduling second.'),['systemd'],['M08']),
L('OS-L04',B('Discos, montajes y recuperación','Disks, mounts and recovery'),B('¿El backup conserva lo que necesitas restaurar?','Does the backup preserve what must be restored?'),B('Distinguir volumen, filesystem, copia, snapshot y restauración.','Distinguish volume, filesystem, backup, snapshot and restore.'),[
 C(B('Capas de almacenamiento','Storage layers'),B('Un dispositivo puede contener particiones y volúmenes; un filesystem organiza contenido y se hace accesible por un montaje. lsblk muestra relaciones y findmnt montajes efectivos. df mide capacidad del filesystem y du recorre archivos accesibles: sus resultados pueden diferir por archivos borrados abiertos, snapshots, reservas, permisos o enlaces. No formatees un disco por reconocer su tamaño; identifica inequívocamente el medio.','A device may contain partitions and volumes; a filesystem organizes contents and is exposed through a mount. lsblk shows relationships and findmnt effective mounts. df measures filesystem capacity while du walks accessible files: results may differ due to deleted open files, snapshots, reserves, permissions or links. Never format a disk because its size looks familiar; identify it unambiguously.'),B('Dispositivo, filesystem y ruta son capas distintas.','Device, filesystem and path are separate layers.')),
 C(B('Qué conserva una copia','What a copy preserves'),B('Un archivo tar agrupa datos y ciertos metadatos; la conservación de ACL y atributos depende de opciones y herramientas. Un hash de contenido no verifica propietario o permisos. LUKS protege datos en reposo según su configuración, pero no impide que una sesión desbloqueada autorizada acceda. Las claves de recuperación se custodian fuera de Git y se prueban por un procedimiento controlado.','A tar archive groups data and selected metadata; ACL and attribute preservation depends on options and tools. A content hash does not verify owner or permissions. LUKS protects data at rest according to configuration but does not prevent access by an authorized unlocked session. Recovery keys stay outside Git and are tested through a controlled process.'),B('Define contenido y metadatos que debes recuperar.','Define content and metadata that recovery needs.')),
 C(B('Recuperar es una operación','Recovery is an operation'),B('RPO expresa pérdida tolerada y RTO tiempo objetivo. Mide qué punto recuperaste y cuánto tardaste. Un snapshot del mismo almacenamiento comparte parte de su dominio de fallo. Restaura primero en otra ruta y compara contenido, permisos y uso funcional. rm no garantiza sanitización en SSD, TRIM o copy-on-write: eliminación lógica y retirada segura del soporte son objetivos diferentes.','RPO expresses tolerated loss and RTO target recovery time. Measure the point recovered and elapsed time. A snapshot on the same storage shares part of its failure domain. Restore to another path first and compare contents, permissions and function. rm does not guarantee sanitization on SSD, TRIM or copy-on-write: logical deletion and safe media retirement have different goals.'),B('Backup existente no es restauración demostrada.','An existing backup is not demonstrated restoration.'))],
 [B('Datos originales','Original data'),B('Archivo de copia','Backup archive'),B('Destino distinto','Separate destination'),B('Contenido y uso verificados','Verified content and use')],
 E(B('Restauración pequeña y medible','Small measurable restore'),'Bash',"work=$(mktemp -d)\nmkdir \"$work/origen\" \"$work/restaurado\"\nprintf 'version 1\n' > \"$work/origen/nota.txt\"\ntar -cf \"$work/copia.tar\" -C \"$work/origen\" .\ntar -tf \"$work/copia.tar\"\ntar -xf \"$work/copia.tar\" -C \"$work/restaurado\"\ncmp \"$work/origen/nota.txt\" \"$work/restaurado/nota.txt\"",B('cmp termina con 0. Debe existir una copia restaurada, no una referencia al original.','cmp returns 0. A restored copy must exist, not a reference to the original.'),B('Solo se extrae el archivo creado por el propio ejercicio. No extraigas archivos desconocidos ni como root. El ejemplo no promete preservar cualquier ACL o atributo.','Only extract the archive created in this exercise. Do not extract unknown archives or run as root. This example does not promise preservation of every ACL or attribute.')),
 P(B('Linux, tar y carpeta temporal del ejemplo. No se requieren discos adicionales ni privilegios.','Linux, tar and the example temporary folder. No extra disks or privileges required.'),[
 S(B('Consulta dispositivos y montajes sin modificar nada.','Read devices and mounts without changing anything.'),B('Relaciona la ruta de trabajo con su filesystem.','Relate the working path to its filesystem.'),'lsblk -f; findmnt -T .'),
 S(B('Ejecuta el ejemplo y guarda el instante inicial/final.','Run the example and record start/end time.'),B('Restauración funcional y duración medida, no estimada.','Functional restore and measured rather than guessed duration.')),
 S(B('Modifica solo la copia restaurada y compara otra vez.','Modify only the restored copy and compare again.'),B('La comparación detecta la diferencia; el original permanece intacto.','Comparison detects a difference; the original stays unchanged.'),'printf "cambio\n" >> "$work/restaurado/nota.txt"'),
 S(B('Compara modo, propietario y contenido por separado.','Compare mode, owner and contents separately.'),B('Declara qué metadatos cubre realmente el método.','Declare the metadata actually covered.'),'stat "$work/origen/nota.txt" "$work/restaurado/nota.txt"')],B('Archivo de copia, registro de restauración y comprobaciones.','Backup archive, restore record and checks.'),B('Recuperas una versión identificada y distingues hash, permisos y apertura útil.','Recover an identified version and distinguish hashes, permissions and useful access.'),B('Tras entregar evidencia, elimina solo los archivos conocidos y directorios vacíos del ejemplo.','After submitting evidence, remove only known example files and empty directories.'),B('El archivo de copia está en el mismo disco que el original.','The backup archive is on the original disk.'),B('Sirve para ensayar el método, no para demostrar resiliencia ante fallo del disco. Diseña un destino independiente.','It rehearses the method, not resilience against disk failure. Design an independent destination.')),
 Q(B('¿Un hash idéntico prueba ACL idénticas?','Does an identical hash prove identical ACLs?'),[B('No.','No.'),B('Sí.','Yes.'),B('Solo con SHA-256.','Only with SHA-256.')],0,B('El hash ordinario compara bytes; inspecciona metadatos aparte.','An ordinary hash compares bytes; inspect metadata separately.')),B('Usar un respaldo no probado como garantía de recuperación.','Treating an untested backup as a recovery guarantee.'),B('El resultado de una copia se valida restaurándolo.','Validate a backup by restoring it.'),['coreutils','nist-media'],['M09']),
L('OS-L05',B('Red, SSH y recursos compartidos','Networking, SSH and shared resources'),B('¿Está escuchando solo donde debería?','Is the service listening only where intended?'),B('Diagnosticar un host y transferir un archivo por un canal autorizado.','Diagnose a host and transfer a file through an authorized channel.'),[
 C(B('Estado del host','Host state'),B('ip muestra interfaces y rutas; ss sockets. Una escucha en 127.0.0.1 no equivale a 0.0.0.0 y una regla de entrada no define toda la salida. El resolvedor utilizado depende de la distribución. getent consulta resolución integrada; resolvectl solo existe en entornos que lo incorporan. Comprueba DNS, transporte y aplicación de forma separada.','ip shows interfaces and routes; ss shows sockets. Listening on 127.0.0.1 is not equivalent to 0.0.0.0, and an ingress rule does not define all egress. The resolver depends on the distribution. getent uses integrated resolution; resolvectl only exists where provided. Check DNS, transport and application separately.'),B('Proceso, interfaz y puerto forman una exposición.','Process, interface and port define exposure.')),
 C(B('Confianza remota','Remote trust'),B('SSH cifra la sesión y verifica identidad del servidor según sus claves de host. Antes de aceptar una clave, contrasta su huella por un canal independiente del docente. No uses StrictHostKeyChecking=no para evitar una advertencia. La cuenta remota debe tener alcance limitado. SFTP transfiere archivos mediante el canal SSH; contenido, permisos y propietario se verifican al llegar.','SSH encrypts the session and checks server identity using host keys. Before accepting a key, compare its fingerprint through an independent instructor channel. Do not use StrictHostKeyChecking=no to avoid a warning. The remote account needs limited scope. SFTP transfers files over SSH; verify content, permissions and owner at the destination.'),B('Cifrado no sustituye verificar el destino.','Encryption does not replace destination verification.')),
 C(B('SMB y NFS añaden autorización','SMB and NFS add authorization'),B('Una carpeta remota depende del protocolo, identidad, reglas del recurso y permisos del almacenamiento. Montar correctamente no demuestra capacidad de escribir ni administrar ACL. La traducción UID/GID o identidades de dominio puede producir diferencias. El diseño del laboratorio separa lector y editor, exige prueba denegada y prohíbe publicar SMB/NFS directamente a Internet.','A remote folder depends on protocol, identity, share rules and storage permissions. A successful mount does not prove write access or ACL administration. UID/GID translation or domain identities can introduce differences. The lab separates reader and editor, requires a denied operation and does not expose SMB/NFS directly to the Internet.'),B('Conectar es anterior a autorizar.','Connecting comes before authorization.'))],
 [B('Interfaz y ruta','Interface and route'),B('Nombre y transporte','Name and transport'),B('Identidad remota','Remote identity'),B('Operación y evidencia','Operation and evidence')],
 E(B('Inventario de exposición propia','Inspect your own exposure'),'Linux CLI','ip -brief address\nip route\nss -lnt\ngetent hosts localhost',B('Direcciones, rutas y escuchas del host propio. Los valores varían por imagen.','Own-host addresses, routes and listeners. Values depend on the image.'),B('No es un escaneo de otros equipos. Relaciona cada escucha con la función prevista; para ver procesos de otras cuentas podrían hacer falta permisos.','This does not scan other machines. Relate each listener to its intended function; viewing other accounts processes may need permission.')),
 P(B('Dos VMs asignadas, SSH preparado por el docente, huella de host publicada por canal independiente, cuentas de práctica y archivo sintético.','Two assigned VMs, instructor-configured SSH, host fingerprint shared through an independent channel, lab accounts and a synthetic file.'),[
 S(B('Ejecuta el inventario local y dibuja el flujo permitido al servidor asignado.','Run the local inventory and draw the allowed flow to the assigned server.'),B('Origen, destino, protocolo, puerto e identidad explícitos.','Explicit source, destination, protocol, port and identity.')),
 S(B('Abre una sesión SSH únicamente al nombre y cuenta entregados por el docente; verifica la huella antes de aceptar.','Open SSH only to the instructor-provided name and account; verify the fingerprint before accepting.'),B('Una discrepancia detiene la práctica. El ejemplo no contiene credenciales comunes.','A mismatch stops the lab. The example supplies no shared credentials.')),
 S(B('Transfiere el archivo mediante el cliente SFTP interactivo; comprueba nombre y destino antes de put.','Transfer the file with the interactive SFTP client; verify name and destination before put.'),B('Solo datos ficticios en la carpeta autorizada; comparación SHA-256 en ambos extremos.','Only synthetic data in the authorized folder; compare SHA-256 at both ends.')),
 S(B('Prueba lectura y escritura en el recurso compartido docente con cada rol.','Test reading and writing the instructor share with each role.'),B('Una denegación prevista es un resultado correcto, no motivo para elevar permisos.','Expected denial is a correct result, not a reason to elevate.'))],B('Mapa de flujo, huella contrastada, hashes y matriz de acceso.','Flow map, checked fingerprint, hashes and access matrix.'),B('Separas diagnóstico local, confianza, transferencia y permisos.','Separate local diagnosis, trust, transfer and access control.'),B('Cierra sesiones y retira solo el archivo transferido tras conservar evidencia; revoca accesos temporales según el docente.','Close sessions and remove only the transferred file after preserving evidence; revoke temporary access as instructed.'),B('DNS resuelve pero el puerto rechaza la conexión.','DNS resolves but the port refuses the connection.'),B('Verifica listener, dirección y firewall del laboratorio; no desactives toda la protección.','Check lab listener, address and firewall; do not disable all protection.')),
 Q(B('¿ss -lnt demuestra acceso desde otro segmento?','Does ss -lnt prove access from another segment?'),[B('Sí.','Yes.'),B('No; solo muestra escuchas TCP locales.','No; it only shows local TCP listeners.'),B('Solo si DNS funciona.','Only when DNS works.')],1,B('La conectividad efectiva requiere rutas y controles además del listener.','Effective connectivity requires routes and controls beyond a listener.')),B('Aceptar una clave de host cambiada sin comprobar su procedencia.','Accepting a changed host key without checking provenance.'),B('Administra destinos definidos; registra lo permitido y lo denegado.','Administer defined targets; record allowed and denied operations.'),['openssh','ubuntu-network'],['M10','M24']),
L('OS-L06',B('Bash: una automatización que sabe fallar','Bash: automation that can fail correctly'),B('¿Qué devolverá tu script ante una ruta inválida?','What will your script return for an invalid path?'),B('Crear una CLI de inventario de solo lectura, probar entradas y separar errores.','Create a read-only inventory CLI, test inputs and separate errors.'),[
 C(B('Contrato antes del bucle','Contract before the loop'),B('Un script debe declarar intérprete, entradas, salida y efectos. Este ejemplo admite exactamente una carpeta y procesa archivos regulares inmediatos, sin seguir enlaces. No recorre todo el equipo ni cuenta directorios. Devuelve 2 para entrada inválida, 1 para fallo de lectura y 0 al completar. Esos códigos son una decisión de nuestra CLI, no una ley universal de Unix.','A script declares interpreter, input, output and effects. This example accepts exactly one directory and processes immediate regular files without following symlinks. It neither traverses the whole computer nor counts directories. It returns 2 for invalid input, 1 for a read failure and 0 for completion. These codes are this CLI contract, not a universal Unix law.'),B('Define qué hace y qué no hace.','Define both goals and non-goals.')),
 C(B('Expansión segura','Safe expansion'),B('Los argumentos se mantienen entre comillas. nullglob impide procesar un patrón literal si no hay coincidencias; dotglob incluye ocultos. Se prueba cada archivo y la salida de wc. No se ejecuta nada obtenido de los nombres. El glob puede enumerar muchos archivos: para una flota real se necesitarían límites y otra estrategia. Aquí el dataset es pequeño y controlado.','Arguments stay quoted. nullglob prevents processing a literal pattern when no match exists; dotglob includes hidden files. Each file and wc result is checked. Nothing derived from a filename is executed. A glob can enumerate many files; a real fleet would require limits and another strategy. Here the dataset is small and controlled.'),B('Nombres como argumentos, nunca como código.','Names are arguments, never code.')),
 C(B('Errores y pruebas','Errors and tests'),B('set -e no reemplaza un diseño explícito de fallos. Una tubería puede ocultar el error de una etapa si solo se mira la última. Captura el estado cuando corresponde, envía diagnósticos a stderr y evita éxito falso después de un fallo parcial. La revisión estática ayuda, pero no sustituye casos: vacío, espacios, ocultos, enlace, ruta inexistente y permiso denegado.','set -e does not replace explicit failure design. A pipeline can hide an earlier error if only the final stage is inspected. Capture status at the right time, send diagnostics to stderr and avoid false success after partial failure. Static checking helps but does not replace cases: empty directory, spaces, hidden file, symlink, nonexistent path and denied permission.'),B('Probar el fallo es parte de la función.','Testing failure is part of functionality.'))],
 [B('Validar entrada','Validate input'),B('Seleccionar archivos','Select files'),B('Medir o registrar fallo','Measure or record failure'),B('Datos + estado final','Data + final status')],
 E(B('inventario.sh, sin modificar entradas','inventario.sh, without modifying inputs'),'Bash',"#!/usr/bin/env bash\nif (( $# != 1 )) || [[ ! -d $1 ]]; then\n  printf 'Uso: inventario.sh CARPETA\n' >&2; exit 2\nfi\nshopt -s nullglob dotglob\ncount=0; bytes=0; failed=0\nfor f in \"$1\"/*; do\n  [[ -f $f && ! -L $f ]] || continue\n  if n=$(wc -c < \"$f\"); then\n    ((count+=1)); ((bytes+=n))\n  else failed=1; fi\ndone\nprintf 'files=%s bytes=%s\n' \"$count\" \"$bytes\"\nexit \"$failed\"",B('En una carpeta con un archivo ASCII de 3 bytes: files=1 bytes=3 y estado 0.','With one 3-byte ASCII file: files=1 bytes=3 and status 0.'),B('Guarda el script fuera del dataset. Los contadores son datos, los diagnósticos son stderr. La salida puede ser parcial cuando el estado es 1.','Save the script outside the dataset. Counters are data, diagnostics go to stderr. Output may be partial when status is 1.')),
 P(B('Bash, editor y una carpeta nueva. No requiere sudo ni red.','Bash, an editor and a new directory. No sudo or network needed.'),[
 S(B('Guarda el ejemplo y valida sintaxis antes de ejecutarlo.','Save the example and validate syntax before execution.'),B('No hay error de sintaxis; eso aún no acredita resultados correctos.','No syntax error; correctness is not yet established.'),'bash -n inventario.sh'),
 S(B('Prepara un archivo de 3 bytes y ejecuta la CLI.','Prepare a 3-byte file and run the CLI.'),B('files=1 bytes=3.','files=1 bytes=3.'),'d=$(mktemp -d); printf abc > "$d/a.txt"; bash inventario.sh "$d"'),
 S(B('Añade un archivo vacío y un enlace al primero.','Add an empty file and a symlink to the first.'),B('files=2 bytes=3; el enlace no se cuenta.','files=2 bytes=3; the symlink is excluded.'),'touch "$d/vacio.txt"; ln -s a.txt "$d/enlace"; bash inventario.sh "$d"'),
 S(B('Prueba sin argumento y con una carpeta vacía distinta.','Test no argument and a separate empty directory.'),B('Sin argumento: estado 2. Carpeta vacía: files=0 bytes=0, estado 0.','No argument: status 2. Empty directory: files=0 bytes=0, status 0.'),'bash inventario.sh; printf "estado=%s\n" "$?"')],B('Script, contrato y tabla de cuatro pruebas.','Script, contract and four-test table.'),B('Las entradas no se modifican y no confundes salida parcial con éxito.','Inputs stay unchanged and partial output is not confused with success.'),B('Retira únicamente el script y dataset propios después de entregar la versión revisada.','Remove only your script and dataset after submitting the reviewed version.'),B('El script se guardó dentro de la carpeta medida.','The script was saved inside the measured directory.'),B('Pasa a ser una entrada y cambia el resultado. Separa herramienta, entrada y salida.','It becomes input and changes the result. Separate tool, input and output.')),
 Q(B('¿bash -n ejecuta y valida el resultado funcional?','Does bash -n execute and validate functional output?'),[B('Sí.','Yes.'),B('No; comprueba sintaxis.','No; it checks syntax.'),B('Solo con sudo.','Only with sudo.')],1,B('Se requieren pruebas de entrada y salida además del análisis sintáctico.','Input/output tests are required in addition to syntax checking.')),B('Conectar texto no confiable a eval o a una shell.','Feeding untrusted text to eval or a shell.'),B('La automatización fiable tiene límites y errores explícitos.','Reliable automation has explicit limits and failures.'),['bash','coreutils'],['M11','M12']),
L('OS-L07',B('Logs y detección con contexto','Logs and contextual detection'),B('¿Una línea coincidente demuestra un incidente?','Does a matching line prove an incident?'),B('Correlacionar eventos y documentar alcance, reloj y ausencia de datos.','Correlate events and document scope, time and missing data.'),[
 C(B('Fuentes y cobertura','Sources and coverage'),B('journalctl consulta registros de journal; syslog y audit tienen configuración y objetivos propios. Una fuente puede no estar habilitada, haber rotado o ser inaccesible al usuario. Registra host, proveedor, intervalo, zona y permisos. No declares equipo limpio porque una consulta devuelve cero filas. El envío centralizado añade recepción e indexación: también pueden fallar.','journalctl queries the journal; syslog and audit have their own configuration and purpose. A source may be disabled, rotated or inaccessible. Record host, provider, interval, timezone and permission. Never declare a host clean because a query returns no rows. Central collection adds reception and indexing, which can also fail.'),B('Sin cobertura no hay conclusión negativa fiable.','Without coverage, negative conclusions are unreliable.')),
 C(B('Indicador frente a comportamiento','Indicator versus behavior'),B('Un hash o dominio conocido orienta una búsqueda, pero necesita tipo, procedencia, vigencia y coincidencia adecuada. Un cambio de grupo, servicio o ACL puede ser legítimo: relaciónalo con ticket y ventana. Las búsquedas por subcadenas generan falsos positivos. El caso usa campos delimitados y valores exactos; no se contactan dominios observados ni se descarga contenido.','A known hash or domain guides a search but needs type, provenance, validity and suitable matching. A group, service or ACL change can be legitimate; correlate it with an approved change and time window. Substring matching produces false positives. This case uses delimited fields and exact values without contacting observed domains or downloading content.'),B('Coincidencia, contexto y corroboración.','Match, context and corroboration.')),
 C(B('Evidencia proporcional','Proportionate evidence'),B('Una consulta en vivo genera actividad y puede cambiar metadatos. Acota y documenta el impacto. Conserva el original, trabaja sobre copia y registra transformaciones temporales. Antes de contener un servicio, considera disponibilidad y evidencia volátil. La decisión de respuesta necesita autoridad, objetivo y prueba de recuperación; no se delega a una salida de IA o a una regla sin contexto.','A live query creates activity and may affect metadata. Bound and document its impact. Preserve originals, work on copies and record time transformations. Before containing a service, consider availability and volatile evidence. Response needs authority, purpose and recovery checks; do not delegate it to an AI output or context-free rule.'),B('Hecho, hipótesis y decisión van separados.','Fact, hypothesis and decision stay separate.'))],
 [B('Fuente y tiempo','Source and time'),B('Filtro de campo','Field filter'),B('Cambio autorizado o anomalía','Approved change or anomaly'),B('Corroborar y decidir','Corroborate and decide')],
 E(B('Un indicador exacto, no una subcadena','Exact indicator, not a substring'),'Bash',"d=$(mktemp -d)\nprintf 'id|destino|resultado\nE1|example.test|allow\nE2|not-example.test|deny\nE3|example.test|deny\n' > \"$d/eventos.txt\"\nawk -F'|' 'NR>1 && $2==\"example.test\" {print $1, $3}' \"$d/eventos.txt\"",B('E1 allow y E3 deny; E2 debe quedar fuera.','E1 allow and E3 deny; E2 must be excluded.'),B('Dataset inventado. allow y deny describen una decisión registrada, no prueban por sí solos ejecución maliciosa ni exfiltración.','Invented dataset. allow and deny describe a logged decision, not proof of malicious execution or exfiltration.')),
 P(B('Archivo sintético del ejemplo y, opcionalmente, journal de la unidad creada en OS-L03.','Synthetic example file and optionally the journal of the OS-L03 unit.'),[
 S(B('Genera el archivo y calcula su hash antes del análisis.','Generate the file and hash it before analysis.'),B('Origen declarado como sintético.','Origin declared synthetic.'),'sha256sum "$d/eventos.txt"'),
 S(B('Ejecuta el filtro exacto y un filtro literal de línea; compara.','Run the exact field filter and a literal line filter; compare.'),B('La búsqueda de línea incluye E2; el filtro de campo no.','The line search includes E2; field matching does not.'),'grep -F "example.test" "$d/eventos.txt"'),
 S(B('Añade una hipótesis alternativa legítima para E1.','Add a plausible legitimate alternative hypothesis for E1.'),B('La hipótesis se separa del contenido realmente observado.','Separate hypothesis from observed data.')),
 S(B('Consulta la unidad de OS-L03 en una ventana corta o registra que no existe.','Query the OS-L03 unit in a short window or record its absence.'),B('Ausencia de fuente y ausencia de actividad no se equiparan.','Do not equate absent source with absent activity.'),'journalctl --user -u os-classroom-demo.service --since "15 minutes ago" --no-pager')],B('Original, hash, consulta exacta, falso positivo y conclusión limitada.','Original, hash, exact query, false positive and bounded conclusion.'),B('Devuelves E1/E3 sin atribuir un incidente no demostrado.','Return E1/E3 without claiming an unproved incident.'),B('Conserva evidencia mínima; elimina solo datos de ensayo según retención. No borres logs del sistema.','Preserve minimum evidence; remove only test data under retention policy. Do not erase system logs.'),B('Una búsqueda por texto devuelve más coincidencias de las esperadas.','A text search returns too many matches.'),B('Identifica el campo y define igualdad exacta; prueba un negativo parecido.','Identify the field, define exact equality and test a similar negative.')),
 Q(B('¿Cero eventos prueba que no hubo actividad?','Do zero events prove no activity?'),[B('Siempre.','Always.'),B('No, depende de cobertura y retención.','No; coverage and retention matter.'),B('Sí con root.','Yes with root.')],1,B('La evidencia negativa requiere una fuente capaz de observar el hecho.','Negative evidence requires a source capable of observing the event.')),B('Bloquear automáticamente por un nombre o una única línea.','Automatically blocking based on a name or single line.'),B('Detección útil combina semántica y cobertura.','Useful detection combines semantics and coverage.'),['systemd','nist-ir'],['M27','M28','M29']),
L('OS-L08',B('Bastionar y demostrar recuperación','Harden and demonstrate recovery'),B('¿Puedes protegerlo sin romper la operación?','Can you secure it without breaking operation?'),B('Aplicar un cambio mínimo, demostrar el control y recuperar un servicio de aula.','Apply a minimal change, demonstrate the control and recover a classroom service.'),[
 C(B('Baseline por función','Role-specific baseline'),B('Una estación personal, un servidor web y un sensor no necesitan la misma exposición. Empieza por soporte, software, cuentas, listeners, permisos, configuración de acceso remoto, logs y copias. CIS y guías del fabricante orientan una baseline, pero cumplir una lista no demuestra por sí solo conformidad completa. Registra aplicable, no aplicable y no evaluado, y justifica excepciones con caducidad.','A personal workstation, web server and sensor need different exposure. Start with support, software, accounts, listeners, permissions, remote access, logs and backups. CIS and vendor guidance inform a baseline, but a checklist alone does not establish complete conformity. Record applicable, not applicable and unassessed controls, and justify expiring exceptions.'),B('El control responde a una función y riesgo.','A control responds to a role and risk.')),
 C(B('Cambios pequeños y protección por capas','Small changes and layered protection'),B('Firewall, permisos, identidad del servicio, SELinux/AppArmor y restricciones de systemd aportan capas diferentes. No deshabilites una capa para resolver un fallo sin diagnosticarlo. Prueba cambios en clon, conserva consola y modifica un objetivo por vez. La apertura de un puerto debe justificar clientes, protocolo y dirección; una salida innecesaria también es exposición.','Firewall, permissions, service identity, SELinux/AppArmor and systemd restrictions provide different layers. Do not disable a layer to solve an undiagnosed failure. Test changes on a clone, preserve console access and change one goal at a time. An open port needs justified clients, protocol and address; unnecessary egress is exposure too.'),B('Una prueba permitida y una denegada.','One allowed test and one denied test.')),
 C(B('Operación e investigación','Operation and investigation'),B('Un hallazgo debe relacionarse con evidencia, impacto plausible, responsable y prueba de corrección. Si aparece una anomalía, conserva estado inicial antes de arreglarla. Medir salud, detectar cambios y recuperar datos son competencias distintas. El cierre requiere volver a usar el servicio con la identidad prevista y comprobar que no quedan accesos temporales, tareas o datos de ensayo.','A finding needs evidence, plausible impact, owner and correction test. When an anomaly appears, preserve initial state before fixing it. Measuring health, detecting changes and restoring data are separate skills. Closure requires useful service access under the intended identity and checking for leftover temporary grants, jobs or data.'),B('Corregir, verificar y documentar el residuo.','Correct, verify and document remaining risk.'))],
 [B('Estado inicial','Initial state'),B('Cambio aprobado','Approved change'),B('Prueba funcional y negativa','Functional and negative test'),B('Rollback verificado','Verified rollback')],
 E(B('Contrato del mini-proyecto Linux','Linux mini-project contract'),'Control record','Activo: carpeta del aula\nRiesgo: acceso de otra identidad\nControl: ACL de lectura limitada\nPrueba positiva: lector abre nota\nPrueba negativa: lector no escribe\nRecuperación: retirar ACL temporal',B('Un control concreto, con resultado falsable.','A concrete, falsifiable control.'),B('No es una plantilla de cumplimiento completa. Usa el experimento nativo de OS-L02 y la recuperación de OS-L04 como evidencia.','This is not a complete compliance template. Use the native OS-L02 experiment and OS-L04 recovery as evidence.')),
 P(B('Misma VM y dataset de las lecciones anteriores; cuenta administrativa docente disponible para recuperar, no para operar rutinariamente.','Same VM and dataset as earlier lessons; instructor administrative recovery available, not used for routine operation.'),[
 S(B('Completa inventario de diez controles con evidencia o estado no evaluado.','Inventory ten controls with evidence or an unassessed state.'),B('Incluye actualizaciones, cuentas, permisos, red, logs y copias.','Include updates, accounts, permissions, network, logs and backups.')),
 S(B('Selecciona una desviación de permisos en tu dataset y prepara diff/rollback.','Select a dataset permission deviation and prepare change/rollback.'),B('Sin tocar autenticación o firewall del anfitrión.','No changes to host authentication or firewall.')),
 S(B('Aplica la corrección, verifica con dos identidades y recoge la evidencia mínima.','Apply the fix, test under two identities and collect minimum evidence.'),B('Resultado funcional y restricción coinciden con la matriz.','Function and restriction match the matrix.')),
 S(B('Restaura en otra ruta, ejecuta inventario.sh y entrega el runbook a un compañero.','Restore to another path, run inventario.sh and hand the runbook to a peer.'),B('El compañero reproduce sin instrucciones verbales ni secretos.','The peer reproduces without verbal instructions or secrets.'))],B('Inventario, ticket, matriz, prueba de restauración y runbook.','Inventory, change record, matrix, restore test and runbook.'),B('Demuestras administración, protección, observación y recuperación en la misma VM.','Demonstrate administration, protection, observation and recovery on the same VM.'),B('Retira únicamente los cambios temporales y valida el estado final; conserva evidencias fuera de la VM restaurada.','Remove only temporary changes and validate final state; keep evidence outside the restored VM.'),B('El control bloquea también el uso legítimo.','The control also blocks legitimate use.'),B('Revierte y revisa el alcance. No marques el control conforme hasta que ambas pruebas pasen.','Revert and review scope. Do not mark the control verified until both tests pass.')),
 Q(B('¿Instalado equivale a verificado?','Does installed mean verified?'),[B('No; falta probar resultado efectivo.','No; effective behavior must be tested.'),B('Sí con un producto conocido.','Yes with a known product.'),B('Sí si no hay alertas.','Yes if there are no alerts.')],0,B('Estado, cobertura y pruebas deben acompañar al control.','State, coverage and tests must accompany a control.')),B('Aplicar un hardening universal sin copia ni contexto.','Applying universal hardening without backup or context.'),B('Un sistema administrable también debe poder recuperarse.','An administrable system must also be recoverable.'),['ubuntu-security','nist-ir'],['M12','M25','M30','M32'])
]
